package net.minecraft.nbt;import java.util.*;public class CompoundTag {public Map<String,Object> data=new HashMap<>();public void put(String k,Object v){data.put(k,v);}public void putUUID(String k,UUID v){put(k,v);}public UUID getUUID(String k){return (UUID)data.get(k);}public void putDouble(String k,double v){put(k,v);}public double getDouble(String k){return ((Number)data.getOrDefault(k,0)).doubleValue();}public void putLong(String k,long v){put(k,v);}public long getLong(String k){return ((Number)data.getOrDefault(k,0)).longValue();}public void putString(String k,String v){put(k,v);}public String getString(String k){return (String)data.getOrDefault(k,"");}public void putInt(String k,int v){put(k,v);}public int getInt(String k){return ((Number)data.getOrDefault(k,0)).intValue();}public void putBoolean(String k,boolean v){put(k,v);}public boolean getBoolean(String k){return Boolean.TRUE.equals(data.get(k));}public boolean contains(String k){return data.containsKey(k);}public CompoundTag getCompound(String k){return (CompoundTag)data.getOrDefault(k,new CompoundTag());}public Set<String> getAllKeys(){return data.keySet();}public ListTag getList(String k,int type){return (ListTag)data.getOrDefault(k,new ListTag());}}